(()=>{'use strict';
const $=s=>document.querySelector(s),el=(tag,text='')=>{const n=document.createElement(tag);n.textContent=text;return n;};
const names=['Сашин','Наташин','С серой крышей'],panel=$('#rental-battery-panel'),list=$('#rental-battery-list'),status=$('#rental-battery-status'),pageLink=$('#rental-battery-admin-link');
if(!panel||!list)return;
const money=v=>Number.isFinite(v)?new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',maximumFractionDigits:0}).format(v):'—';
const when=v=>Number.isFinite(v)?new Date(v).toLocaleTimeString('ru-RU',{timeZone:'Europe/Moscow',hour:'2-digit',minute:'2-digit'}):'—';
const num=(v,digits=1,unit='')=>Number.isFinite(v)?Number(v).toLocaleString('ru-RU',{maximumFractionDigits:digits})+unit:'—';
const api=async(path,body)=>{const r=await fetch('/api/admin/'+path,{cache:'no-store',credentials:'same-origin',...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})});let d;try{d=await r.json();}catch{throw Error('Сервер вернул некорректный ответ.');}if(!r.ok)throw Object.assign(Error(d.error||'Не удалось выполнить запрос.'),{status:r.status});return d;};
const states={armed:'Ожидаем сигнал', 'departure-candidate':'Возможен выход',away:'Вероятно на воде','return-candidate':'Возможен возврат',returned:'Возврат сигнала подтверждён',dismissed:'Событие отклонено'};
const cards=new Map(),busy=new Set(),tripAttempts=new Map();let timer=null,loading=false,user=null,rentals=[],lastPollAt=0;
const duration=v=>{if(!Number.isFinite(v)||v<0)return '—';const n=Math.round(v),h=Math.floor(n/60),m=n%60;return h?`${h} ч ${m} мин`:`${m} мин`;};
function valid(device){return device.online===true&&device.stale===false&&device.bmsConnected===true&&Number.isFinite(device.socPercent);}
function fleetSummary(devices){const allFresh=devices.length>0&&devices.every(valid),soc=allFresh?Math.min(...devices.map(d=>d.socPercent)):null,states=devices.map(d=>d.state);let mode='unknown',runtime='—',caption='Нет свежих данных';if(!devices.length)caption='Нет аккумулятора';else if(!allFresh)caption='Проверьте связь';else if(states.every(s=>s==='charging')){mode='charging';const estimates=devices.map(d=>d.estimatedChargeMinutes);runtime=estimates.every(Number.isFinite)?duration(Math.max(...estimates)):'—';caption='Заряжается · до полного заряда';}else if(states.every(s=>s==='discharging')){mode='discharging';const estimates=devices.map(d=>d.estimatedMinutes);runtime=estimates.every(Number.isFinite)?duration(Math.min(...estimates)):'—';caption='Работы';}else if(states.every(s=>s==='idle')){mode='idle';caption='Ожидание';}else caption='Разное состояние';return {allFresh,soc,mode,runtime,caption};}
function setupSummary(view){if(view.summaryButton)return;const button=el('button');button.type='button';button.className='rental-battery-summary';button.setAttribute('aria-expanded','false');const ring=el('span');ring.className='rental-battery-ring';const charge=el('b');const content=el('span');content.className='rental-battery-summary-copy';const title=el('strong',view.article.dataset.catamaran);const runtime=el('b');runtime.className='rental-battery-runtime';const caption=el('small');const socList=el('small');socList.className='rental-battery-summary-soc';content.append(title,runtime,caption,socList);ring.append(charge);button.append(ring,content,el('span','›'));const details=el('div');details.className='rental-battery-details';details.hidden=true;for(const child of [...view.article.children])details.append(child);view.article.append(button,details);button.onclick=()=>{const expanded=button.getAttribute('aria-expanded')!=='true';button.setAttribute('aria-expanded',String(expanded));details.hidden=!expanded;};view.summaryButton=button;view.summaryRing=ring;view.summaryCharge=charge;view.summaryRuntime=runtime;view.summaryCaption=caption;view.summarySocList=socList;view.details=details;}
function updateSummary(view,devices){setupSummary(view);view.lastDevices=devices;const summary=fleetSummary(devices);view.summaryButton.dataset.mode=summary.mode;view.summaryButton.dataset.fresh=String(summary.allFresh);view.summaryButton.dataset.charge=summary.allFresh?(summary.soc>=50?'high':summary.soc>=20?'medium':'low'):'unknown';view.summaryCharge.textContent=summary.allFresh?num(summary.soc,0,'%'):'—';view.summaryRing.style.setProperty('--soc',summary.allFresh?`${Math.max(0,Math.min(100,summary.soc))}%`:'0%');view.summaryRuntime.textContent=summary.runtime==='—'?'—':`≈ ${summary.runtime}`;view.summaryCaption.textContent=summary.caption;view.summarySocList.textContent=summary.allFresh?devices.map(d=>num(d.socPercent,0,'%')).join(' / '):'—';devices.forEach((device,index)=>{const row=view.readings.children[index];if(!row||row.classList.contains('rental-battery-no-device'))return;const mode=device.state==='charging'?'Заряжается':device.state==='discharging'?'Разряжается':device.state==='idle'?'Ожидание':'Состояние неизвестно';const estimate=valid(device)?device.state==='charging'?device.estimatedChargeMinutes:device.state==='discharging'?device.estimatedMinutes:null:null;const eta=Number.isFinite(estimate)?` · ${device.state==='charging'?'до полного заряда':'работы'} ≈ ${duration(estimate)}`:'';const metric=el('span',`Напряжение ${num(device.voltageV,2,' В')} · Ток ${num(device.currentA,1,' А')} · Температура ${num(device.temperatureC,1,' °C')}`);const state=el('small',`${mode}${eta} · ESP32 ${device.online===true?'на связи':device.online===false?'не в сети':'—'} · BMS ${device.bmsConnected===true?'на связи':device.bmsConnected===false?'нет связи':'—'} · измерено ${when(device.lastMeasuredAt)}`);row.children[2]?.replaceWith(metric);row.children[3]?.replaceWith(state);});}
function makeCard(label){const article=el('article');article.className='rental-battery-card';article.dataset.catamaran=label;const head=el('div');head.className='rental-battery-head';const h=el('h3',label),tripBadge=el('span');tripBadge.className='rental-battery-trip-badge';head.append(h,tripBadge);const readings=el('div');readings.className='rental-battery-readings';const deviceLine=el('p');deviceLine.className='rental-battery-device';const trip=el('div');trip.className='rental-battery-trip';const select=el('select');select.setAttribute('aria-label','Оплаченная аренда катамарана для '+label);const arm=el('button','Связать с арендой');arm.type='button';arm.className='rental-battery-action';const armStatus=el('p');armStatus.className='rental-battery-message';const confirmDeparture=el('button','Подтвердить выход');confirmDeparture.type='button';const confirmReturn=el('button','Подтвердить сигнал возврата');confirmReturn.type='button';const dismiss=el('button','Отклонить событие');dismiss.type='button';const tripActions=el('div');tripActions.className='rental-battery-actions';tripActions.append(confirmDeparture,confirmReturn,dismiss);const due=el('p');due.className='rental-battery-due';const explanation=el('p');explanation.className='rental-battery-explanation';trip.append(select,arm,armStatus,tripActions,due,explanation);article.append(head,readings,deviceLine,trip);const view={article,h,tripBadge,readings,deviceLine,select,arm,armStatus,tripActions,confirmDeparture,confirmReturn,dismiss,due,explanation};view.arm.onclick=()=>mutate(label,'arm',null,view);view.confirmDeparture.onclick=()=>{const pending=view.trip?.departurePending===true;if(pending){mutate(label,'confirm-departure',view.trip,view);return;}if(confirm('Подтвердить предполагаемый выход по BLE? Это отметит только событие датчика и не изменит аренду или оплату.'))mutate(label,'confirm-departure',view.trip,view);};view.confirmReturn.onclick=()=>{if(confirm('Подтвердить сигнал вероятного возврата? Это отметит только событие датчика. Аренда останется активной; для закрытия используйте «Вернуть» в списке аренд, где при необходимости отдельно подтвердите доплату.'))mutate(label,'confirm-return',view.trip,view);};view.dismiss.onclick=()=>{const unassign=['armed','away'].includes(view.trip?.state);if(confirm(unassign?'Снять привязку катамарана от аренды? Платёжные данные не изменятся.':'Отклонить это событие датчика? Данные аренды и оплаты не изменятся.'))mutate(label,'dismiss',view.trip,view);};select.addEventListener('change',()=>{view.selectedRental=select.value;});select.addEventListener('blur',()=>{if(view.latestLinkedCounts)updateOptions(view,view.latestNow,view.latestLinkedCounts);});cards.set(label,view);list.append(article);return view;}
function updateOptions(view,now,linkedCounts){view.latestLinkedCounts=linkedCounts;view.latestNow=now;const available=rentals.filter(r=>(linkedCounts.get(r.id)||0)<(Number.isSafeInteger(r.quantity)?r.quantity:1));const signature=available.map(r=>`${r.id}:${r.start}:${r.expectedReturn}:${r.quantity}:${r.clientLabel}`).join('|');if(signature===view.optionSignature&&view.select.options.length)return;const focused=document.activeElement===view.select;if(focused)return;const selected=view.selectedRental||view.select.value;view.select.replaceChildren(el('option','Выберите аренду…'));view.select.options[0].value='';for(const r of available){const option=el('option',`№${r.id} · ${r.clientLabel||'Клиент'} · ${when(r.start)}–${when(r.expectedReturn)} · ${r.quantity} шт.`);option.value=String(r.id);view.select.append(option);}view.optionSignature=signature;const nearest=available.slice().sort((a,b)=>Math.abs((a.start||now)-now)-Math.abs((b.start||now)-now))[0];view.select.value=available.some(r=>String(r.id)===selected)?selected:nearest?String(nearest.id):'';view.selectedRental=view.select.value;view.arm.disabled=!available.length||busy.has(view.article.dataset.catamaran);}
function updateTrip(view,trip){view.trip=trip||null;const candidate=trip?.state==='departure-candidate',returnCandidate=trip?.state==='return-candidate';view.tripBadge.textContent=trip?states[trip.state]||trip.state:'Нет связанной аренды';view.tripBadge.dataset.state=trip?.state||'none';view.dismiss.textContent=['armed','away'].includes(trip?.state)?'Снять привязку':'Отклонить событие';view.arm.hidden=!!trip&&['armed','departure-candidate','away','return-candidate'].includes(trip.state);view.select.hidden=view.arm.hidden;view.tripActions.hidden=!candidate&&!returnCandidate&&!['armed','away'].includes(trip?.state);view.confirmDeparture.hidden=!candidate;view.confirmReturn.hidden=!returnCandidate;view.dismiss.hidden=!trip||!['armed','departure-candidate','away','return-candidate'].includes(trip.state);view.due.hidden=!trip||!Number.isFinite(trip.dueRub);view.due.textContent=Number.isFinite(trip?.dueRub)?`Предварительная доплата по аренде: ${money(trip.dueRub)}${trip.estimated?' · оценка по тарифу':''}${Number.isFinite(trip.rentalQuantity)&&trip.rentalQuantity>1?` · за аренду целиком (${trip.rentalQuantity} катамарана)`:''}`:'';if(trip?.estimated&&Number.isFinite(trip.quoteMinutes)&&trip.quoteMinutes>0)view.due.textContent+=` · опоздание округлено до ${trip.quoteMinutes} мин`;if(Number.isFinite(trip?.existingDueRub)&&trip.existingDueRub>0)view.due.textContent+=` · уже начислено ${money(trip.existingDueRub)}`;if(Number.isFinite(trip?.overtimeQuoteRub)&&trip.overtimeQuoteRub>0)view.due.textContent+=` · ориентир за опоздание ${money(trip.overtimeQuoteRub)}`;view.explanation.textContent=trip?.state==='return-candidate'?'Если нужно начислить доплату за опоздание, сначала оформите продление +30/+60 минут в аренде, затем нажмите «Вернуть» и подтвердите оплату. Подтверждение сигнала здесь не принимает деньги.':trip?.state==='departure-candidate'?(trip.departurePending?'Подтверждение отметит фактическое отплытие через действующее действие проката и запустит оплаченное время, затем подтвердит сигнал BLE. Новых списаний не будет.':'Подтверждение фиксирует только событие BLE; сведения об аренде и оплате не меняются.') : '';if(trip){const eventTime=trip.detectedReturnAt||trip.detectedDepartureAt;view.armStatus.textContent=`Аренда №${trip.rentalId} · ${trip.clientLabel||'Клиент'} · ${when(trip.start)}–${when(trip.expectedReturn)}${eventTime?' · сигнал '+when(eventTime):''}`;}else view.armStatus.textContent='';}
function render(data){rentals=Array.isArray(data.rentals)?data.rentals:[];const boats=new Map((data.catamarans||[]).map(x=>[x.label,x]));for(const label of names)if(!cards.has(label))makeCard(label);for(const boat of data.catamarans||[])if(boat.label&&!cards.has(boat.label))makeCard(boat.label);const linkedIds=new Map();for(const trip of (data.catamarans||[]).map(x=>x.trip).filter(t=>t&&['armed','departure-candidate','away','return-candidate'].includes(t.state)))linkedIds.set(trip.rentalId,(linkedIds.get(trip.rentalId)||0)+1);for(const [label,view] of cards){const boat=boats.get(label),devices=Array.isArray(boat?.devices)?boat.devices:[];view.article.dataset.state=devices.every(valid)&&devices.length?'fresh':devices.length?'stale':'unknown';view.article.hidden=!boat;view.readings.replaceChildren();for(const device of devices){const row=el('div');row.className='rental-battery-reading';row.dataset.freshness=device.online===false?'offline':device.stale===true?'stale':device.online===true?'fresh':'unknown';row.dataset.state=device.state||'unknown';const heading=el('strong',device.name||'Аккумулятор');const soc=el('b',num(device.socPercent,1,'%'));soc.className='rental-battery-soc';soc.dataset.charge=Number.isFinite(device.socPercent)?device.socPercent>=50?'high':device.socPercent>=20?'medium':'low':'unknown';const metrics=el('span',`Напряжение ${num(device.voltageV,2,' В')} · Ток ${num(device.currentA,1,' А')} · Температура ${num(device.temperatureC,1,' °C')}`);const mode=device.state==='charging'?'Заряжается':device.state==='discharging'?'Разряжается':device.state==='idle'?'Ожидание':'Состояние неизвестно';const eta=device.state==='charging'?device.estimatedChargeMinutes:device.state==='discharging'?device.estimatedMinutes:null;const runtime=Number.isFinite(eta)?` · ${device.state==='charging'?'до полного заряда':'работы'} ≈ ${duration(eta)}`:'';const state=el('small',`${mode}${runtime} · ESP32 ${device.online===true?'на связи':device.online===false?'не в сети':'—'} · BMS ${device.bmsConnected===true?'на связи':device.bmsConnected===false?'нет связи':'—'} · измерено ${when(device.lastMeasuredAt)}`);row.append(heading,soc,metrics,state);view.readings.append(row);}if(!devices.length){const noDevice=el('p','Нет привязанного аккумулятора.');noDevice.className='rental-battery-no-device';view.readings.append(noDevice);}view.deviceLine.textContent=devices.length>1?`${devices.length} отдельных аккумулятора · заряд не усредняется`:'';updateSummary(view,devices);updateTrip(view,boat?.trip||null);updateOptions(view,data.now||Date.now(),linkedIds);}status.textContent='';}
function publishOverview(data){window.STARTBatteryOverview=data;document.dispatchEvent(new CustomEvent('start:battery-overview',{detail:data}));}
async function markRentalDeparture(trip,attempt,view){if(attempt.rentalDepartureDone)return;const body=attempt.rentalDepartureBody||(attempt.rentalDepartureBody={id:trip.rentalId,revision:trip.rentalRevision,batteryTripId:trip.id,batteryTripRevision:trip.revision});try{await api('rental-depart',body);attempt.rentalDepartureDone=true;return;}catch(error){if(error.status===409||!error.status||error.status>=500){await refresh();if(view.trip?.id===trip.id&&view.trip.state==='away'&&view.trip.departurePending===false){attempt.rentalDepartureDone=true;return;}}throw error;}}
async function mutate(label,action,trip,view){if(busy.has(label))return;const key=`${label}:${action}:${trip?.id||view.select.value||'new'}`;let attempt=tripAttempts.get(key);if(!attempt){let tripBody;if(action==='arm'){const rentalId=Number(view.select.value);if(!Number.isSafeInteger(rentalId)||rentalId<1){view.armStatus.textContent='Выберите конкретную аренду.';return;}tripBody={action,label,rentalId,requestId:crypto.randomUUID()};}else{if(!trip)return;tripBody={action,tripId:trip.id,revision:trip.revision,requestId:crypto.randomUUID()};}attempt={tripBody,rentalDepartureBody:null,rentalDepartureDone:false};tripAttempts.set(key,attempt);}const atomicDeparture=action==='confirm-departure'&&trip?.departurePending===true;busy.add(label);view.arm.disabled=true;for(const b of [view.confirmDeparture,view.confirmReturn,view.dismiss])b.disabled=true;view.armStatus.textContent=atomicDeparture?'Отмечаем отплытие и подтверждаем сигнал датчика…':'Сохраняем отметку…';try{if(atomicDeparture){await markRentalDeparture(trip,attempt,view);tripAttempts.delete(key);await refresh();}else{await api('battery-trips',attempt.tripBody);tripAttempts.delete(key);await refresh();}}catch(error){if(error.status&&error.status<500)tripAttempts.delete(key);if(attempt.rentalDepartureDone)await refresh();view.armStatus.textContent=error.message||'Не удалось сохранить отметку.';if(attempt.rentalDepartureDone)view.armStatus.textContent='Отплытие отмечено. '+view.armStatus.textContent;if(!error.status||error.status>=500)view.armStatus.textContent+=' Ответ не подтверждён; повторите действие безопасно.';}finally{busy.delete(label);view.arm.disabled=!view.select.value;for(const b of [view.confirmDeparture,view.confirmReturn,view.dismiss])b.disabled=false;}}
async function refresh(){if(loading||document.hidden||!user)return;loading=true;lastPollAt=Date.now();try{const data=await api('battery-overview');render(data);publishOverview(data);panel.hidden=false;}catch(error){publishOverview(null);panel.hidden=false;status.textContent='Связь с сервером не подтверждена; показания скрыты до успешного обновления. '+(error.status===403?'Доступ ограничен ролями сотрудника и администратора.':error.message||'Не удалось обновить данные.');for(const view of cards.values()){view.article.dataset.state='unknown';if(view.summaryButton){view.summaryButton.dataset.fresh='false';view.summaryButton.dataset.mode='unknown';view.summaryCharge.textContent='—';view.summaryRuntime.textContent='—';view.summaryCaption.textContent='Нет свежих данных';view.summarySocList.textContent='—';view.summaryRing.style.setProperty('--soc','0%');}for(const row of view.readings.children)row.dataset.freshness='unknown';view.armStatus.textContent='Связь с сервером не подтверждена.';}}finally{loading=false;}}
function stop(){if(timer){clearInterval(timer);timer=null;}}function start(){stop();if(!document.hidden&&user)timer=setInterval(()=>{const pending=[...cards.values()].some(view=>view.trip?.departurePending===true&&Number.isSafeInteger(view.trip.rentalId)&&view.trip.rentalId>0);if(Date.now()-lastPollAt>=(pending?5000:15000))refresh();},5000);}
document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();else{refresh();start();}});
(async()=>{try{const session=await api('session');user=session.user;if(!user||!['admin','staff'].includes(user.role)||user.scheduleOnly){panel.hidden=true;return;}pageLink.hidden=user.role!=='admin';await refresh();start();}catch(error){panel.hidden=true;}})();
})();
